mapper.select:
SELECT fnd01_fund_code_id
  FROM fnd01_fund_code
 WHERE fnd01_fund_cd    = #{fundCode}
   AND fnd01_company_id = #{companyId}
 LIMIT 1

SELECT fnd06_office_work_cd
  FROM fnd06_office_work
 WHERE fnd06_company_id = #{companyId}
   AND fnd06_kofia_cd   = #{kofiaCode}
 LIMIT 1

mapper.delete:
DELETE FROM fnd02_fund_info
 WHERE fnd02_work_date    = f_trunc(#{workDate,jdbcType=DATE})
   AND fnd02_fund_code_id = #{fundCodeId}
